 81	  home.sessionPath = [
 82	    "$HOME/.local/bin"
 83	  ];
 84	
 85	  home.file.${moraineConfigRelative}.text = moraineConfig;
 86	
 87	  home.activation.removeLegacyAoeUnits = lib.hm.dag.entryBefore [ "writeBoundary" ] ''
 88	    rm -f \
 89	      "$HOME/.config/systemd/user/aoe-serve.service" \
 90	      "$HOME/.config/systemd/user/aoe-lan-proxy.service" \
 91	      "$HOME/.config/systemd/user/aoe-lan-proxy.socket"
 92	  '';
 93	
 94	  systemd.user.startServices = "sd-switch";
 95	
 96	  # Upstream owns installation, readiness, migrations, and child startup. The
 97	  # foreground wrapper keeps this unit alive only while that complete stack is
 98	  # healthy, so one restart policy accurately represents the operator surface.
 99	  systemd.user.services.moraine = {
100	    Unit = {
101	      Description = "Workstation-local Moraine producer";
102	      X-Restart-Triggers = [ config.home.file.${moraineConfigRelative}.source ];
103	    };
104	
105	    Service = {
106	      Type = "simple";
107	      ExecStart = "${moraineService}/bin/moraine-service ${morainePackage}/bin/moraine ${moraineConfigPath}";
108	      ExecStop = "${moraineControl} down";
109	      Restart = "on-failure";
110	      RestartSec = 5;
111	    };
112	
113	    Install.WantedBy = [ "default.target" ];
114	  };
115	
116	  # installPackages is what creates the profile this handoff reads from. Ordered
117	  # only after reloadSystemd, the handoff ran while ~/.nix-profile was still a
118	  # dangling symlink, so every home.packages tool the updater needs — npm, jq —
119	  # was missing and activation died on whichever one it probed first.
120	  home.activation.bootstrapAgentTools =
121	    lib.hm.dag.entryAfter [ "reloadSystemd" "installPackages" ] ''
122	      # Activation runs with a curated store-only PATH holding just coreutils and
123	      # friends, so system directories are absent. The updater's remaining host
124	      # tools — flock for its lock, curl for the AoE release check, unzip and find
125	      # for the Bun archive — come from the store rather than from whatever the
126	      # host happens to install.
127	      #
128	      # The system directories go last, after everything the store supplies, for
129	      # systemctl alone: the updater restarts a unit in this host's user session,
130	      # so it needs that session's own systemd rather than a store copy of one.

